"""Kaggle code-competition entrypoint for the SOT-2079 GPT champion."""

import base64
import csv
import hashlib
import os
from pathlib import Path


CHAMPION_COMMIT = "925fb85b19d7d6ea5d150131ac349da031a08aaa"
CHAMPION_SHA256 = "6d480375c3b75bc2b650be6a77a3ca9b97308bfb424f2cdd68c2b9c624bdb039"
_ATTACK_PY_B64 = ""

attack_source = base64.b64decode(_ATTACK_PY_B64)
if hashlib.sha256(attack_source).hexdigest() != CHAMPION_SHA256:
    raise RuntimeError("embedded champion SHA-256 mismatch")
Path("/kaggle/working/attack.py").write_bytes(attack_source)

from kaggle_evaluation.jed_attack_134815.jed_attack_inference_server import (
    JEDAttackInferenceServer,
)

server = JEDAttackInferenceServer()
if os.getenv("KAGGLE_IS_COMPETITION_RERUN"):
    server.serve()
else:
    with open("/kaggle/working/submission.csv", "w", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["Id", "Score"])
        writer.writerows(
            [
                ["gpt_oss_public", 0.0],
                ["gpt_oss_private", 0.0],
                ["gemma_public", 0.0],
                ["gemma_private", 0.0],
            ]
        )
    print("Wrote local-run placeholder submission.csv")
